// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/**
 * @title SecureVoting
 * @dev Blockchain-based voting system for academic project
 * Features:
 * - Multiple elections support
 * - One vote per voter per election
 * - Immutable vote records
 * - Admin-only election creation
 * - Transparent vote counting
 */
contract SecureVoting {

    // ==================== STATE VARIABLES ====================

    address public admin; // Contract admin address
    uint256 public electionCount; // Total number of elections created

    // Election structure
    struct Election {
        uint256 id;
        string name;
        string description;
        uint256 candidateCount;
        bool isActive;
        uint256 totalVotes;
    }

    // Candidate structure
    struct Candidate {
        uint256 id;
        string name;
        uint256 voteCount;
    }

    // ==================== MAPPINGS ====================

    // electionId => Election details
    mapping(uint256 => Election) public elections;

    // electionId => candidateId => Candidate details
    mapping(uint256 => mapping(uint256 => Candidate)) public candidates;

    // electionId => voterAddress => hasVoted (true/false)
    mapping(uint256 => mapping(address => bool)) public hasVoted;

    // electionId => voterAddress => candidateId (who they voted for)
    mapping(uint256 => mapping(address => uint256)) public voterChoice;

    // ==================== EVENTS ====================

    event ElectionCreated(uint256 indexed electionId, string name);
    event CandidateAdded(uint256 indexed electionId, uint256 candidateId, string name);
    event VoteCasted(uint256 indexed electionId, address indexed voter, uint256 candidateId);
    event ElectionStatusChanged(uint256 indexed electionId, bool isActive);

    // ==================== MODIFIERS ====================

    /**
     * @dev Restricts function access to only admin
     */
    modifier onlyAdmin() {
        require(msg.sender == admin, "Only admin can perform this action");
        _;
    }

    /**
     * @dev Checks if election exists
     */
    modifier electionExists(uint256 _electionId) {
        require(_electionId > 0 && _electionId <= electionCount, "Election does not exist");
        _;
    }

    /**
     * @dev Checks if election is active
     */
    modifier electionIsActive(uint256 _electionId) {
        require(elections[_electionId].isActive, "Election is not active");
        _;
    }

    // ==================== CONSTRUCTOR ====================

    /**
     * @dev Sets the contract deployer as admin
     */
    constructor() {
        admin = msg.sender;
        electionCount = 0;
    }

    // ==================== ADMIN FUNCTIONS ====================

    /**
     * @dev Creates a new election (admin only)
     * @param _name Election name
     * @param _description Election description
     * @param _candidateNames Array of candidate names
     */
    function createElection(
        string memory _name,
        string memory _description,
        string[] memory _candidateNames
    ) public onlyAdmin {
        require(_candidateNames.length > 0, "At least one candidate required");

        electionCount++;

        elections[electionCount] = Election({
            id: electionCount,
            name: _name,
            description: _description,
            candidateCount: _candidateNames.length,
            isActive: true,
            totalVotes: 0
        });

        // Add candidates
        for (uint256 i = 0; i < _candidateNames.length; i++) {
            candidates[electionCount][i + 1] = Candidate({
                id: i + 1,
                name: _candidateNames[i],
                voteCount: 0
            });
        }

        emit ElectionCreated(electionCount, _name);
    }

    /**
     * @dev Toggle election status (admin only)
     * @param _electionId Election ID
     * @param _status New status (true = active, false = inactive)
     */
    function setElectionStatus(uint256 _electionId, bool _status) 
        public 
        onlyAdmin 
        electionExists(_electionId) 
    {
        elections[_electionId].isActive = _status;
        emit ElectionStatusChanged(_electionId, _status);
    }

    // ==================== VOTING FUNCTIONS ====================

    /**
     * @dev Cast a vote in an election
     * @param _electionId Election ID
     * @param _candidateId Candidate ID
     */
    function castVote(uint256 _electionId, uint256 _candidateId) 
        public 
        electionExists(_electionId)
        electionIsActive(_electionId)
    {
        // Check if voter has already voted
        require(!hasVoted[_electionId][msg.sender], "You have already voted in this election");

        // Check if candidate exists
        require(
            _candidateId > 0 && _candidateId <= elections[_electionId].candidateCount,
            "Invalid candidate ID"
        );

        // Record the vote
        hasVoted[_electionId][msg.sender] = true;
        voterChoice[_electionId][msg.sender] = _candidateId;

        // Increment vote counts
        candidates[_electionId][_candidateId].voteCount++;
        elections[_electionId].totalVotes++;

        emit VoteCasted(_electionId, msg.sender, _candidateId);
    }

    // ==================== VIEW FUNCTIONS ====================

    /**
     * @dev Get election details
     * @param _electionId Election ID
     */
    function getElection(uint256 _electionId) 
        public 
        view 
        electionExists(_electionId)
        returns (
            uint256 id,
            string memory name,
            string memory description,
            uint256 candidateCount,
            bool isActive,
            uint256 totalVotes
        )
    {
        Election memory e = elections[_electionId];
        return (e.id, e.name, e.description, e.candidateCount, e.isActive, e.totalVotes);
    }

    /**
     * @dev Get candidate details
     * @param _electionId Election ID
     * @param _candidateId Candidate ID
     */
    function getCandidate(uint256 _electionId, uint256 _candidateId)
        public
        view
        electionExists(_electionId)
        returns (
            uint256 id,
            string memory name,
            uint256 voteCount
        )
    {
        require(
            _candidateId > 0 && _candidateId <= elections[_electionId].candidateCount,
            "Invalid candidate ID"
        );

        Candidate memory c = candidates[_electionId][_candidateId];
        return (c.id, c.name, c.voteCount);
    }

    /**
     * @dev Check if voter has voted in an election
     * @param _electionId Election ID
     * @param _voter Voter address
     */
    function hasVoterVoted(uint256 _electionId, address _voter)
        public
        view
        electionExists(_electionId)
        returns (bool)
    {
        return hasVoted[_electionId][_voter];
    }

    /**
     * @dev Get all candidates for an election
     * @param _electionId Election ID
     */
    function getAllCandidates(uint256 _electionId)
        public
        view
        electionExists(_electionId)
        returns (string[] memory names, uint256[] memory voteCounts)
    {
        uint256 count = elections[_electionId].candidateCount;
        names = new string[](count);
        voteCounts = new uint256[](count);

        for (uint256 i = 0; i < count; i++) {
            Candidate memory c = candidates[_electionId][i + 1];
            names[i] = c.name;
            voteCounts[i] = c.voteCount;
        }

        return (names, voteCounts);
    }
}

